mapper.update:
UPDATE reservations r
  JOIN fairs f
    ON f.fair_id = r.fair_id
   SET r.status = 'CANCELED'
     , r.canceled_at = #{now}
     , r.cancel_reason = #{reason}
     , r.canceled_by = NULL
     , r.updated_at = #{now}
 WHERE r.reservation_id = #{reservationId}
   AND r.status = #{expectedStatus}
   AND f.canceled_at IS NOT NULL

   AND EXISTS (
       SELECT 1
         FROM payment p
         JOIN refund rf
           ON rf.payment_id = p.payment_id
        WHERE p.reservation_id = r.reservation_id
          AND p.payment_type = 'RESERVATION_DEPOSIT'
          AND rf.status = 'COMPLETED'
   )
